({sticky,section}) => {{
  const main = document.querySelector('main');
  switch (sticky) {
    case 'sticky-top':
      {
        const {
          debounce
        } = await import('../../utils/action.js');
        window.addEventListener('resize', debounce(() => handleTopHeight(section)));
        handleTopHeight(section);
        main.prepend(section);
        break;
      }
    case 'sticky-bottom':
      {
        if (section.querySelector(':is(.promobar, .notification)')) {
          const metadata = getMetadata(section.querySelector('.section-metadata'));
          const delay = getDelayTime(metadata.delay?.text);
          if (delay) setTimeout(() => {
            handleStickyPromobar(section, delay);
          }, delay);else handleStickyPromobar(section, delay);
        }
        main.append(section);
        break;
      }
    default:
      break;
  }
}}

tabs/tabs.js.code:
({tabs,tabLists,tabFocus}) => {tabLists.forEach(tabList => {
  tabList.addEventListener('keydown', e => {
    if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
      if (e.key === 'ArrowRight') {
        tabFocus += 1;
        if (tabFocus >= tabs.length) tabFocus = 0;
      } else if (e.key === 'ArrowLeft') {
        tabFocus -= 1;
        if (tabFocus < 0) tabFocus = tabs.length - 1;
      }
      tabs[tabFocus].setAttribute('tabindex', 0);
      tabs[tabFocus].focus();
    }
  });
});}

